local function main(modeData)
    print("Executing: " .. tostring(modeData.Name))
    -- Выполняем скрипт, привязанный к кнопке
    local success, err = pcall(function()
        modeData.Script()
    end)
    if not success then
        warn("Error loading script: " .. tostring(err))
    end
end

