local function validateKey()
    local userKey = KeyInput.Text:gsub("%s+", "")
    if userKey == "" then ShowStatusMessage("Field cannot be empty!", KeySystemData.Colors.Error) return end
    
    ShowStatusMessage("Authenticating...", Color3.fromRGB(200, 200, 200))
    local JunkieKeySystem = loadstring(game:HttpGet("https://junkie-development.de/sdk/JunkieKeySystem.lua"))()
    local isValid = JunkieKeySystem.verifyKey(Config.api, userKey, Config.service)
    
    if isValid then
        ShowStatusMessage("Access Granted!", KeySystemData.Colors.Success)
        task.wait(0.5)
        
        local outTween = SmoothTween(MainFrame, 0.5, {Size = UDim2.new(0, 0, 0, 0)})
        outTween.Completed:Connect(function()
            MainFrame.Visible = false
            SelectionFrame.Visible = true
            SelectionFrame.Position = MainFrame.Position
            SmoothTween(SelectionFrame, 0.6, {Size = UDim2.new(0, 300, 0, 350)})
        end)
    else
        ShowStatusMessage("Invalid License Key!", KeySystemData.Colors.Error)
    end
end

SubmitButton.MouseButton1Click:Connect(validateKey)
