    local JunkieKeySystem = loadstring(game:HttpGet("https://junkie-development.de/sdk/JunkieKeySystem.lua"))()
    local link = JunkieKeySystem.getLink(Config.api, Config.provider, Config.service)
    if link then setclipboard(link) ShowStatusMessage("Link copied!", KeySystemData.Colors.Success) end
end)

KeyInput.FocusLost:Connect(function(enterPressed) if enterPressed then validateKey() end end)

